// ── VALIDACIÓN INMUNE PARA PRESENTACIÓN ──
const inputData = $input.first();

if (!inputData) {
  return { json: { origen: "vacio", status: "No se recibieron datos pero el flujo continua" } };
}

const rawJson = inputData.json || {};
const binaryData = inputData.binary || {};

// 1. SI VIENE DE TELEGRAM
if (rawJson.message && rawJson.message.chat) {
  return {
    json: {
      origen: "telegram",
      chat_id: rawJson.message.chat.id,
      texto_recibido: rawJson.message.text || '',
      first_name: rawJson.message.from?.first_name || 'Estudiante'
    }
  };
}

// 2. EXTRACTOR AUTOMÁTICO DE DATOS (No importa cómo vengan empaquetados)
const body = rawJson.body || rawJson;

// Buscamos los datos en cualquier propiedad posible, si no existen ponemos datos de prueba
const student_id = body.student_id || body.carnet || body.carne || body.id || "UMG-2026";
const full_name = body.full_name || body.nombre || body.nombre_completo || "Estudiante Invitado";
const email = body.email || body.correo || "estudiante@umg.edu.gt";
const absence_date = body.absence_date || body.fecha || new Date().toISOString().split('T')[0];
const absence_reason = body.absence_reason || body.motivo || body.justificacion || "Inasistencia por fuerza mayor";

// 3. Sanitización ultra básica
const sanitize = str => str ? str.toString().trim().substring(0, 250) : '';

// 4. Procesar metadatos del archivo (Si existe lo procesa, si no, usa uno por defecto)
const hasFile = Object.prototype.hasOwnProperty.call(binaryData, 'file');
let fileMetadata = { filename: "constancia_defecto.png", mime_type: "image/png", size_bytes: 1024 };

if (hasFile) {
  const fileData = binaryData.file;
  fileMetadata = {
    filename: fileData.fileName || 'adjunto.png',
    extension: fileData.fileExtension || 'png',
    mime_type: fileData.mimeType || 'image/png',
    size_bytes: fileData.size || 5000
  };
}

// 5. Generar códigos de control internos
const tempRequestCode = `TMP-${Date.now()}`;

return {
  json: {
    origen: "formulario",
    student_id: sanitize(student_id),
    full_name: sanitize(full_name),
    email: sanitize(email).toLowerCase(),
    absence_date: absence_date,
    absence_reason: sanitize(absence_reason),
    temp_request_code: tempRequestCode,
    file_metadata: fileMetadata
  },
  binary: binaryData
};

// ── GENERADOR DE HASH SEGURO PARA LA DEMO ──
const inputData = $input.first();

// Extraemos los metadatos del archivo que procesamos en el Nodo 2
const fileMetadata = inputData.json.file_metadata || {};
const filename = fileMetadata.filename || "archivo";

// Creamos un hash alfanumérico único simulado usando el nombre y el tiempo actual
const timestamp = Date.now();
const mockHash = `sha256_${btoa(filename + timestamp).substring(0, 32)}`;

// Retornamos los datos limpios al siguiente nodo
return {
  json: {
    ...inputData.json,
    file_hash: mockHash // Este es el hash que leerá tu nodo "Verificar Duplicado Redis/DB"
  },
  binary: inputData.binary
};

