-- 1. Asegurar que exista la columna o tabla para registrar los hashes
CREATE TABLE IF NOT EXISTS registro_hashes (
    hash_archivo VARCHAR(100) PRIMARY KEY,
    fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 2. Buscar si el hash que calculamos en el nodo anterior ya existe
SELECT 
    CASE 
        WHEN EXISTS (
            SELECT 1 FROM registro_hashes WHERE hash_archivo = '{{ $json.file_hash }}'
        ) THEN 'true'
        ELSE 'false'
    END as duplicado;

